/* 仅用于 UI 评审的虚构数据。所有写操作只更新浏览器本地，不调用真实业务或发送短信。 */
const UI = (() => {
  const paths={arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',back:'m14 6-6 6 6 6',calendar:'M5 4h14v17H5zM8 2v5m8-5v5M5 10h14',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Zm-7-2v4',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',info:'M12 11v6m0-10v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0m5 8a4 4 0 0 1 4 4v3m-5-19a4 4 0 0 1 0 8',user:'M20 21v-3a5 5 0 0 0-5-5H9a5 5 0 0 0-5 5v3M16 5a4 4 0 1 1-8 0 4 4 0 0 1 8 0',home:'m3 10 9-8 9 8v11h-6v-7H9v7H3z',ticket:'M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4V5Zm12 0v14',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',file:'M5 2h9l5 5v15H5zM14 2v6h5M8 12h8m-8 4h8',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',close:'m6 6 12 12M6 18 18 6',money:'M3 5h18v14H3zM8 12h.01M16 12h.01M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0',lock:'M5 10h14v12H5zM8 10V6a4 4 0 0 1 8 0v4m-4 5v3',qr:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM15 14h6v7h-7v-3h4',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0m-1 5 6 6',award:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M8 10l-3 12 7-4 7 4-3-12',shuttle:'m9 13-5-9 5-2 6 2 5 5-9 7M4 4l9 9M9 2l7 10m-3 1a4 4 0 0 1-5 5l-1-1 5-5z',retry:'M3 11a9 9 0 1 1 3 8M3 4v7h7'};
  const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.info}"/></svg>`;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const badge=(t,c='')=>`<span class="badge ${c}">${esc(t)}</span>`;
  const yuan=n=>'¥'+Number(n).toFixed(2);
  const key='aisports-ui-prototype-v1';
  const seed=()=>({version:1,phase:'registration',hosting:'normal',publication:'published',mode:'manual-paid',fieldsLocked:true,configVersion:1,read:false,fields:[{name:'常用持拍手',type:'单选枚举',required:true},{name:'参赛经验（年）',type:'数字',required:false},{name:'备注',type:'文本',required:false}],orders:[
    {id:'DEMO-1001',person:'林一（示例）',owner:'me',unit:'男子双打',due:120,status:'submitted',declared:true,members:['林一（示例）','周末球友（示例）'],receipts:[],refunds:[],checked:false,match:false,refundState:'none',submitted:'2026-10-07 10:18'},
    {id:'DEMO-1002',person:'陈晨（示例）',owner:'other',unit:'男子单打',due:60,status:'submitted',declared:true,members:['陈晨（示例）'],receipts:[{id:'REC-1',payer:'陈晨（示例）',amount:60,time:'2026-10-07 09:35',reversed:false}],refunds:[],checked:false,match:false,refundState:'none',submitted:'2026-10-07 09:20'},
    {id:'DEMO-1003',person:'徐晓（示例）',owner:'other',unit:'女子单打',due:0,status:'approved',declared:false,members:['徐晓（示例）'],receipts:[],refunds:[],checked:false,match:false,refundState:'none',submitted:'2026-10-07 08:40'},
    {id:'DEMO-1004',person:'刘宁（示例）',owner:'other',unit:'男子单打',due:60,status:'approved',declared:true,members:['刘宁（示例）'],receipts:[{id:'REC-2',payer:'刘宁（示例）',amount:60,time:'2026-10-07 08:20',reversed:false}],refunds:[],checked:false,match:false,refundState:'none',submitted:'2026-10-07 08:10'}],notifications:{station:'已入站',sms:'待发送'}});
  function load(){try{const s=JSON.parse(localStorage.getItem(key));if(s?.version===1)return s}catch{}return seed()}
  let state=load();
  const received=o=>o.receipts.filter(r=>!r.reversed).reduce((n,r)=>n+r.amount,0);
  const refunded=o=>o.refunds.reduce((n,r)=>n+r.amount,0);
  const net=o=>received(o)-refunded(o);
  const automatic=()=>state.mode.startsWith('auto');
  const normal=()=>state.hosting==='normal';
  const beforeStart=()=>['pre_registration','registration','registration_closed'].includes(state.phase);
  const canApprove=o=>normal()&&beforeStart()&&o.status==='submitted'&&net(o)>=o.due;
  function save(){localStorage.setItem(key,JSON.stringify(state))}
  function syncFromStorage(event){if(event.key!==key)return false;state=load();return true}
  function automaticApproval(o){if(automatic()&&canApprove(o))o.status='approved'}
  function change(fn){fn(state);state.orders.forEach(automaticApproval);save()}
  function reset(mode='manual-paid'){state=seed();state.mode=mode;if(mode.endsWith('free')){state.orders.forEach(o=>{o.due=0;o.receipts=[];o.declared=false})}state.orders.forEach(automaticApproval);save()}
  const order=id=>state.orders.find(o=>o.id===id);
  const myOrders=()=>state.orders.filter(o=>o.owner==='me');
  const phaseLabel=()=>({pre_registration:'报名未开始',registration:'报名中',registration_closed:'报名已截止',ongoing:'进行中',finished:'已结束'}[state.phase]);
  function status(o){if(!normal())return ['赛事已取消','red'];if(o.status==='withdrawn')return ['已撤回','gray'];if(o.status==='rejected')return ['未通过','red'];if(o.status==='approved')return ['已通过',''];if(!beforeStart())return ['审核窗口已结束','gray'];if(o.due>net(o))return [o.declared?'待核对到账':'待付款','orange'];return ['待人工审核','blue']}
  const refundLabel=o=>({none:'无退款办理',pending:'待处理',progress:'办理中',done:'已退款',not_needed:'无需退款'}[o.refundState]);
  const canPay=o=>normal()&&beforeStart()&&['submitted'].includes(o.status)&&o.due>net(o);
  const withdrawReason=o=>!normal()?'赛事已取消，请查看资金收尾':!['submitted','approved'].includes(o.status)?'当前报名已失效':o.checked?'整单已有成员报到，不能撤回':o.match?'已有场次关联，不能撤回':o.status==='approved'&&state.phase!=='registration'?'已通过报名只可在报名截止前撤回':'';
  function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3800)}
  let returnFocus;
  function modal(title,body,footer=''){returnFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h3>${esc(title)}</h3><button class="close" data-action="close" aria-label="关闭">${icon('close')}</button></div>${body}${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`;setTimeout(()=>document.querySelector('.modal input,.modal select,.modal button')?.focus(),0)}
  const close=()=>{const hasModal=Boolean(document.querySelector('.modal'));document.getElementById('overlay').innerHTML='';if(hasModal)returnFocus?.focus()};
  const brand=()=>`<a class="brand" href="index.html#home"><img src="brand.svg" alt="临时品牌标识"><div><span class="brand-name">AI运动</span><span class="brand-sub">身边的运动生活</span></div></a>`;
  const art=()=>`<svg class="court-art" viewBox="0 0 520 320" aria-hidden="true"><defs><pattern id="grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M0 35V0h35" fill="none" stroke="#ceddc7" stroke-width=".6"/></pattern></defs><rect width="520" height="320" fill="url(#grid)"/><ellipse cx="280" cy="272" rx="167" ry="20" fill="#b5ceb0" opacity=".35"/><g transform="translate(70 53) skewY(-8)"><path d="M40 210 125 43h265l-85 167Z" fill="#467959"/><path d="m62 195 69-137h234l-69 137Z" fill="none" stroke="#dce8d2" stroke-width="2"/><path d="m97 127 235 0m-153-69-70 137m210-137-70 137m-94-68-34 68" fill="none" stroke="#dce8d2" stroke-width="1.4"/><path d="m99 117 225 0M97 99v49m229-49v49" fill="none" stroke="#f1f1d8" stroke-width="2"/><path d="m102 103 221 0m-224 7h225m-221 9h214" stroke="#d8dfc3" stroke-width=".7"/></g><g transform="translate(345 39) rotate(23)"><ellipse cx="32" cy="49" rx="29" ry="41" fill="#edf0d7" stroke="#d47a42" stroke-width="6"/><path d="M7 30h48M4 42h55M5 55h53M10 69h44M20 12v74m12-78v81m12-76v69" stroke="#bbccb0" stroke-width="1"/><path d="M32 90v65" stroke="#d47a42" stroke-width="7"/><path d="M32 137v27" stroke="#f2c299" stroke-width="9"/></g><g transform="translate(326 204) rotate(-25)"><path d="m0 0-29-50 13-6 15 6 13-6 13 6-20 50Z" fill="#fcfcf3" stroke="#c2d0b4"/><path d="M-16-54 3-4M2-51 3-3M17-54 3-2" stroke="#c2d0b4"/><ellipse cx="3" cy="3" rx="10" ry="8" fill="#d58b54"/></g><circle cx="140" cy="42" r="6" fill="#da8751"/><path d="M117 36h13m-6-6v12" stroke="#dfb881" stroke-width="2"/></svg>`;
  const scenarios=()=>`<div class="scenario"><span>${icon('settings')} 原型演示场景</span><select aria-label="审核费用场景" data-scenario="mode"><option value="manual-paid" ${state.mode==='manual-paid'?'selected':''}>收费 · 人工审核</option><option value="auto-paid" ${state.mode==='auto-paid'?'selected':''}>收费 · 无需审核</option><option value="manual-free" ${state.mode==='manual-free'?'selected':''}>免费 · 人工审核</option><option value="auto-free" ${state.mode==='auto-free'?'selected':''}>免费 · 无需审核</option></select><select aria-label="赛事时间场景" data-scenario="phase">${['registration','registration_closed','ongoing','finished'].map(p=>`<option value="${p}" ${state.phase===p?'selected':''}>${({registration:'报名中',registration_closed:'报名截止',ongoing:'进行中',finished:'已结束'})[p]}</option>`).join('')}</select><button class="btn text slim" data-action="reset">重置演示</button></div>`;
  document.addEventListener('click',e=>{if(e.target.closest('[data-action="close"]'))close()});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.modal')){e.preventDefault();e.stopImmediatePropagation();close();return}if(e.key==='Tab'){const dialog=document.querySelector('.modal')||document.querySelector('.drawer');if(!dialog)return;const f=[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea,a[href]')];if(!f.length)return;if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}});
  return {icon,esc,badge,yuan,syncFromStorage,get s(){return state},change,reset,order,myOrders,net,received,refunded,automatic,normal,beforeStart,canApprove,status,refundLabel,canPay,withdrawReason,toast,modal,close,brand,art,scenarios};
})();
